        'details.metaballs.description.try_count': 'How many balls n enter the sum F(p). The more balls there are, the more often they meet and merge.',
        'details.metaballs.description.try_isolation': 'The threshold τ. A higher value makes every ball shrink, so that balls only merge when they come very close; a lower value makes the metaballs swell and flow together earlier.',
        'details.metaballs.description.try_spread': 'How far the balls move away from the centre.',
        'details.metaballs.description.try_colours': 'The colours of the lit side and of the shaded side of the lava.',
